import{_ as e,o as a,c as i,a2 as r}from"./chunks/framework.DPTp4bo7.js";const u=JSON.parse('{"title":"反应池混用实用可能性探究（已被抛弃）","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/exploring-practical-mixed-recipe-reactor-crucibles"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/exploring-practical-mixed-recipe-reactor-crucibles"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/exploring-practical-mixed-recipe-reactor-crucibles"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/exploring-practical-mixed-recipe-reactor-crucibles"}]]},"headers":[],"relativePath":"zh/exploring-practical-mixed-recipe-reactor-crucibles.md","filePath":"zh/page-rJRctcbf03vvLbgMp7b1iL.md"}'),t={name:"zh/exploring-practical-mixed-recipe-reactor-crucibles.md"};function c(s,p,o,l,d,n){return a(),i("div",null,[...p[0]||(p[0]=[r('<div class="logistics-content"><span class="logistics-source-anchor" id="反应池混用实用可能性探究-已被抛弃" aria-hidden="true"></span><h1 id="反应池混用实用可能性探究-已被抛弃" tabindex="-1">反应池混用实用可能性探究（已被抛弃） <a class="header-anchor" href="#反应池混用实用可能性探究-已被抛弃" aria-label="Permalink to &quot;反应池混用实用可能性探究（已被抛弃）&quot;">​</a></h1><blockquote><p>源页面 ID：<code>rJRctcbf03vvLbgMp7b1iL</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=rJRctcbf03vvLbgMp7b1iL" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><details><summary>聊天记录-1</summary><p>xyIvneu_:</p><p>给句话，反应池能不能压，如果不能，困难在哪里</p><p>?caution?caution?:</p><p>等我复现一下那个bug</p><p>压可以压，但是这个状态感觉十分脆弱</p><p>@xyIvneu_ 就是这么个情况</p><p>视频再传。你无法保证不堵塞</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-5eca694d45e1e92e.jpeg" alt="反应池混用实用可能性探究（已被抛弃）"></p><p>合成两种废液</p><p>两个配方不能同周期</p><p>一旦有一个配方阻塞，那么反应池就不工作了</p><p>Cipolla_:</p><p>看来风险不小</p><p>c:</p><p>所以是同时反应的吗</p><p>这不就和箱子一样，要是两种东西进箱子，一种仓库满了，另一种就堵了</p><p>?caution?caution?:</p><p>必定会同时反应吧</p><p>回复xyIvneu_:给句话，反应池能不能压，如果不能，困难在哪里</p><p>@xyIvneu_ 困难在你很难保证水和污水不积压</p><p>madSUN:</p><p>谁来描述一下反应池的现状</p><p>多个反应不是无法同时进行吗</p><p>?caution?caution?:</p><p>无法避免死锁问题</p><p>madSUN:</p><p>我没看懂，究竟是哪一步的问题，是多个反应本来就无法同时进行，还是进行后会卡？</p><p>?caution?caution?:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-565ac0edf18d7277.jpeg" alt="反应池混用实用可能性探究（已被抛弃）"></p><p>格子只有5个，但是6个要同时存在</p><p>一旦反应池某个反应卡死，那么反应池就会直接卡死</p><p>无法一个反应不能完成，但是另一个反应继续的情况</p><p>应该是，如果A反应卡死了，即使可以通过B反应脱离卡死，但是一旦卡死，机器就停了，所以B反应无法进行</p></details><p>聊天记录-1AI总结：反应池不能压，困难在于死锁风险：两个配方不能同周期，格子不足（5格需同时存6物），一旦某反应卡死，整个池停止，无法通过其他反应自救。</p><details><summary>实验结果-1</summary><p>水<em>50+废液</em>50+液化息壤<em>50+占位符A</em>0+占位符B*0→阻塞</p><p>...</p></details><details><summary>聊天记录-2</summary><p>xyIvneu_</p><p>试了一下完全不行，反应池魔术目前暂告破产</p><p>苍孤狼</p><p>所以是在试啥</p><p>2倍速的反应池溶液配方？</p><p>xyIvneu_</p><p>我完全想不通为什么锦草和芽针一起输入只占一格</p><p>水和污水一起输入就堵住了</p><p>我只能怀疑是内部爱优化了锦草芽针产线</p><p>madSUN</p><p>回复 xyIvneu_: 我完全想不通为什么锦草和芽针一起输入只占一格</p><p>有没有可能是液体和传送带的处理逻辑不同</p><p>比如试试看锦草 + 息壤会怎么样</p><p>xyIvneu_</p><p>回复 madSUN: 比如试试看锦草 + 息壤会怎么样</p><p>只占一格</p><p>回复 madSUN: 有没有可能是液体和传送带的处理逻辑不同</p><p>我也怀疑，但是是不可证伪的东西</p><p>苍孤狼</p><p>两种不同固体可以满速输入且共用同一格？</p><p>可惜液态息壤转变成壤晶废液配方有4个不同液体，没办法和别的配方合并</p><p>壤晶合成加液化息壤合成 液体：水 壤晶废液 污水 液化息壤 固体：输入：蓝铁粉末 息壤 输出：壤晶 液体占4格，两个固体输入占1格，壤晶占1格，6格还是超了</p><p>固体输出是瞬时的，那如果这三个固体能只占一格就能完成合并</p></details><details><summary>实验结果</summary><p>当反应原料在反应后归零时，若外部有新物品待进入，反应池“有可能”阻止物品进入，也可能不阻止。</p></details><p>反应池原理推测被合并到反应池特性整理中，反应池优化被合并到版本开荒中</p></div>',1)])])}const g=e(t,[["render",c]]);export{u as __pageData,g as default};
